pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        amount = bound(amount, 0, 1 ether);

        RevertingThenCounting callee = new RevertingThenCounting();

        vm.deal(address(this), amount);

        bool ok;
        try c.sendMoney(address(callee), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract RevertingThenCounting {
    uint public calls;
    fallback() external payable {
        calls += 1;
        revert("boom");
    }
}
